head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > updateServerTime]<br/>서버(WAS)의 현재 시간을 비동기로 조회하여 기준 시간을 갱신하고 Promise 객체로 반환합니다.",
    "validation" : [
        "$p.updateServerTime() 호출 시 Promise 객체를 반환해야 합니다.",
        "then 콜백의 resolve 인자로 서버의 현재 시간을 'yyyyMMddHHmmssSSS' 형식(17자리)의 문자열로 받을 수 있어야 합니다.",
        "async/await 방식으로 호출 시 동일하게 'yyyyMMddHHmmssSSS' 형식(17자리)의 문자열을 반환받을 수 있어야 합니다.",
        "updateServerTime 호출 이후 $p.getCurrentServerDate() 로 갱신된 기준 시간을 조회할 수 있어야 합니다.",
        "이미 서버 시간 요청이 진행 중인 경우 중복 요청 없이 즉시 반환되어야 합니다.",
        "서버 응답이 유효하지 않으면 reject 되어 catch 콜백이 호출되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.serverTimeRegex = /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])([01]\d|2[0-3])([0-5]\d){2}\d{3}$/;

scwin.validateResult = function (serverTime) {
    if (typeof serverTime !== "string") {
        return "[검증] 반환값이 문자열이 아님 → FAIL";
    }
    var lengthOk = (serverTime.length === 17);
    var formatOk = scwin.serverTimeRegex.test(serverTime);
    return "[검증] 길이(17) : " + (lengthOk ? "PASS" : "FAIL") + " / 형식(yyyyMMddHHmmssSSS) : " + (formatOk ? "PASS" : "FAIL");
};



scwin.btn_updateServerTime_onclick = async function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // then 콜백 방식
        var ret = $p.updateServerTime();
        wf_body_bottom.getObj("scwin").setReturnValue("$p.updateServerTime() 반환 타입 : " + (ret instanceof Promise ? "Promise" : typeof ret));
        if (ret instanceof Promise) {
            ret.then(function (serverTime) {
                wf_body_bottom.getObj("scwin").setReturnValue("then resolve 값 : " + serverTime);
                wf_body_bottom.getObj("scwin").setReturnValue(scwin.validateResult(serverTime));
            }, function (error) {
                wf_body_bottom.getObj("scwin").setReturnValue("then reject : " + error);
            });
        }
    } else if (scenario === "2") {
        // async/await 방식
        try {
            var serverTime = await $p.updateServerTime();
            wf_body_bottom.getObj("scwin").setReturnValue("await 반환 값 : " + serverTime);
            wf_body_bottom.getObj("scwin").setReturnValue(scwin.validateResult(serverTime));
        } catch (error) {
            wf_body_bottom.getObj("scwin").setReturnValue("await catch : " + error);
        }
    } else if (scenario === "3") {
        // 갱신 후 getCurrentServerDate 확인
        var before = $p.getCurrentServerDate("yyyyMMddHHmmssSSS");
        wf_body_bottom.getObj("scwin").setReturnValue("갱신 전 getCurrentServerDate : " + before);
        $p.updateServerTime().then(function (st) {
            wf_body_bottom.getObj("scwin").setReturnValue("updateServerTime resolve : " + st);
            var after = $p.getCurrentServerDate("yyyyMMddHHmmssSSS");
            wf_body_bottom.getObj("scwin").setReturnValue("갱신 후 getCurrentServerDate : " + after);
            wf_body_bottom.getObj("scwin").setReturnValue("[검증] 기준 시간 갱신 여부 : " + (after >= st.substring(0, 14) ? "PASS" : "확인필요"));
        });
    } else if (scenario === "4") {
        // 중복 호출 테스트 (실제 네트워크 요청 횟수 + Promise 참조 비교)
        wf_body_bottom.getObj("scwin").setReturnValue("--- 중복 요청 테스트 시작 ---");
        var callCount = 0;
        var originalOpen = XMLHttpRequest.prototype.open;
        XMLHttpRequest.prototype.open = function (method, url) {
            if (url && url.indexOf("serverTime.wq") > -1) {
                callCount++;
            }
            return originalOpen.apply(this, arguments);
        };

        var ret1 = $p.updateServerTime();
        var ret2 = $p.updateServerTime();
        var ret3 = $p.updateServerTime();

        wf_body_bottom.getObj("scwin").setReturnValue("1차 호출 반환 타입 : " + (ret1 instanceof Promise ? "Promise" : typeof ret1));
        wf_body_bottom.getObj("scwin").setReturnValue("2차 호출 반환 타입 : " + (ret2 instanceof Promise ? "Promise" : typeof ret2));
        wf_body_bottom.getObj("scwin").setReturnValue("3차 호출 반환 타입 : " + (ret3 instanceof Promise ? "Promise" : typeof ret3));
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] serverTime.wq 실제 요청 횟수 : " + callCount + " → " + (callCount === 1 ? "PASS (중복 방지됨)" : "확인필요 (" + callCount + "회 요청됨)"));

        Promise.all([ret1, ret2, ret3]).then(function (results) {
            wf_body_bottom.getObj("scwin").setReturnValue("1차 resolve 값 : " + results[0]);
            wf_body_bottom.getObj("scwin").setReturnValue("2차 resolve 값 : " + results[1]);
            wf_body_bottom.getObj("scwin").setReturnValue("3차 resolve 값 : " + results[2]);
            var firstIsServerTime = (typeof results[0] === "string" && scwin.serverTimeRegex.test(results[0]));
            var othersImmediate = (results[1] === undefined && results[2] === undefined);
            wf_body_bottom.getObj("scwin").setReturnValue("[검증] 1차만 서버 시간 반환, 이후 호출은 즉시 반환(undefined) : " + ((firstIsServerTime && othersImmediate) ? "PASS" : "확인필요"));
            XMLHttpRequest.prototype.open = originalOpen;
        }, function (error) {
            wf_body_bottom.getObj("scwin").setReturnValue("reject : " + error);
            XMLHttpRequest.prototype.open = originalOpen;
        });
    } else if (scenario === "5") {
        // 서버 응답 실패 (reject)
        var originalOpen = XMLHttpRequest.prototype.open;
        XMLHttpRequest.prototype.open = function (method, url) {
            if (url && url.indexOf("serverTime.wq") > -1) {
                arguments[1] = url.replace("serverTime.wq", "serverTime_invalid.wq");
            }
            return originalOpen.apply(this, arguments);
        };
        wf_body_bottom.getObj("scwin").setReturnValue("서버 응답 실패 상황 재현 → updateServerTime 호출");
        $p.updateServerTime().then(function (st) {
            wf_body_bottom.getObj("scwin").setReturnValue("resolve : " + st + " (확인필요)");
            XMLHttpRequest.prototype.open = originalOpen;
        }, function (error) {
            wf_body_bottom.getObj("scwin").setReturnValue("[검증] reject 호출됨 → PASS");
            XMLHttpRequest.prototype.open = originalOpen;
        });
    }
}
